// A labelled corpus for the prose-name detector (src/pii/names.js).
//
// NAMED: { id, text, names: [...] } - ticket-style text where a person is named by context. `names` lists every exact span the
//   detector should return (in Standard mode), nothing more. Recall and precision are measured over all of them.
// UNCUED: { id, text, names } - names with NO cue around them. Standard mode is expected to miss these (it is cue-driven on
//   purpose); Strict mode is expected to find most of them. They measure what Strict adds.
// TRAPS: { id, text } - ticket-style text with no person in it: vocabulary, products, teams, weekdays, months, placeholders,
//   Title Case ticket titles. Standard mode must return nothing for (almost) all of them.
//
// All names are made up or are common example names; none belongs to a real customer.

const named = (id, text, ...names) => ({ id, text, names });

